async function invoke<C extends Parameters<typeof window.pizzaSocial.invoke>[0]>(channel: C, request: Parameters<typeof window.pizzaSocial.invoke>[1]) {
  if (!window.pizzaSocial?.invoke) throw new Error('The secure desktop connection is unavailable. Open Pizza Promo Pro as the installed desktop app, not in a browser preview, then try again.')
  const result = await window.pizzaSocial.invoke(channel, request as never)
  if (!result.ok) throw new Error(result.error.message)
  return result.data as unknown
}

export function App() {
  const [page, setPage] = useState<Page>('overview')
  const info = useQuery({ queryKey: ['app-info'], queryFn: () => invoke('app:getInfo', {}) as Promise<{ version: string; online: boolean }> })
  const onboarding = useQuery({ queryKey: ['onboarding'], queryFn: () => invoke('onboarding:getStatus', {}) as Promise<OnboardingStatus> })
  const visiblePage:Page=onboarding.data?.shouldShow&&page==='overview'?'setup':page
  const current = navigation.find((item) => item.page === visiblePage)
  const desktopReady=Boolean(window.pizzaSocial?.invoke)
  return <div className="app-shell">
    <aside className="sidebar">
      <div className="brand"><div className="brand-mark"><Pizza size={23} /></div><div><strong>Pizza Promo</strong><span>Pro</span></div></div>
      <nav aria-label="Main navigation">{navigation.map(({ label, page: target, icon: Icon, section }) => <div className="nav-entry" key={target}>{section&&<span className="nav-section">{section}</span>}<button className={visiblePage === target ? 'nav-item active' : 'nav-item'} onClick={() => setPage(target)}><Icon size={18} /><span>{label}</span>{visiblePage === target && <ChevronRight size={15} />}</button></div>)}</nav>
      <div className="sidebar-foot"><span className="status-dot" /> Local workspace<br/><small>Version {info.data?.version ?? '0.1.0'} · Mock providers</small></div>
    </aside>
    <main>
      {!desktopReady&&<div className="desktop-required" role="alert"><ShieldCheck size={17}/><span><strong>Desktop connection unavailable</strong> Open the installed Pizza Promo Pro application to save settings and use local data.</span></div>}
      <header className="topbar"><div><span className="eyebrow">Pizza Promo Pro</span><h1>{current?.label}</h1></div><div className="connection"><span className={info.data?.online ? 'status-dot' : 'status-dot offline'} />{info.data?.online ? 'Online' : 'Offline — planning available'}</div></header>
      <div className="workspace">{visiblePage === 'overview' ? <Overview onNavigate={setPage} /> : visiblePage === 'setup' ? <SetupWorkspace onNavigate={setPage} /> : visiblePage === 'assistant' ? <AiAssistant onNavigate={setPage} /> : visiblePage === 'contentItems' ? <ContentStudio onNavigate={setPage} /> : visiblePage === 'reviewDesk' ? <ReviewDesk /> : visiblePage === 'calendar' ? <LiveCalendar /> : visiblePage === 'ads' ? <AdsWorkspace /> : visiblePage === 'performance' ? <PerformanceWorkspace /> : visiblePage === 'media' ? <Media /> : visiblePage === 'settings' ? <SettingsPage /> : configs[visiblePage] ? <CrudPanel config={configs[visiblePage]!} /> : null}</div>
    </main>
  </div>
}

function Overview({ onNavigate }: { onNavigate: (page: Page) => void }) {
  const content = useQuery({ queryKey: ['records', 'contentItems'], queryFn: () => invoke('data:list', { entity: 'contentItems' }) as Promise<RecordValue[]> })
  const counts = useMemo(() => Object.fromEntries(['idea','draft','ready_for_review','approved','scheduled','published'].map((status) => [status, content.data?.filter((item) => item.status === status).length ?? 0])), [content.data])
  return <>
    <section className="welcome"><div><span className="eyebrow tomato">Your content kitchen</span><h2>Keep the next post moving.</h2><p>Everything starts with verified business facts and ends with your approval.</p></div><button className="primary" onClick={() => onNavigate('contentItems')}>Create a content idea <ChevronRight size={17}/></button></section>
    <section><div className="section-heading"><div><span className="eyebrow">The pizza line</span><h3>Content workflow</h3></div><span className="mock-badge">Human approval required</span></div><div className="status-rail">{[['idea','Ideas'],['draft','Drafts'],['ready_for_review','Review'],['approved','Approved'],['scheduled','Scheduled'],['published','Published']].map(([key,label],index) => <div className="status-card" key={key}><span>{String(index + 1).padStart(2,'0')}</span><strong>{counts[key]}</strong><p>{label}</p></div>)}</div></section>
    <div className="dashboard-grid"><section className="panel"><span className="eyebrow">Quick start</span><h3>Set up the facts first</h3><div className="checklist">{[['Business profile','businesses'],['Store locations','locations'],['Menu and prices','menuItems'],['Current promotions','promotions'],['Ask the AI Assistant','assistant']].map(([label,target], i) => <button key={target} onClick={() => onNavigate(target as Page)}>{target==='assistant'?<Bot size={19}/>:<CheckCircle2 size={19}/>}<span><strong>{label}</strong><small>{target==='assistant'?'Plan and create with saved facts':i === 0 ? 'Start here' : 'Add verified details'}</small></span><ChevronRight size={17}/></button>)}</div></section><section className="panel quiet"><Database size={28}/><h3>Local-first by design</h3><p>Your plans, menu, and drafts remain available without internet. Features that need a connection are clearly labeled.</p></section></div>
  </>
}

function CrudPanel({ config }: { config: NonNullable<(typeof configs)[Page]> }) {
  const client = useQueryClient(), [open, setOpen] = useState(false), [error, setError] = useState(''), [editingId,setEditingId]=useState<string|null>(null)
  const { register, handleSubmit, reset } = useForm<Record<string, string | number>>()
  const records = useQuery({ queryKey: ['records', config.entity], queryFn: () => invoke('data:list', { entity: config.entity }) as Promise<RecordValue[]> })
  const closeEditor=()=>{reset();setOpen(false);setEditingId(null);setError('')}
  const editRecord=(record:RecordValue)=>{const values:Record<string,string|number>={};for(const field of config.fields){const databaseKey=field.key.replace(/[A-Z]/g,(letter)=>`_${letter.toLowerCase()}`),raw=record[field.key]??record[databaseKey];if(raw===undefined||raw===null)continue;if(field.type==='datetime-local'&&typeof raw==='number'){const date=new Date(raw);values[field.key]=new Date(date.getTime()-date.getTimezoneOffset()*60000).toISOString().slice(0,16)}else values[field.key]=raw as string|number}reset(values);setEditingId(String(record.id));setOpen(true);setError('')}
  const save = useMutation({ mutationFn: (value: RecordValue) => invoke('data:save', { entity: config.entity, value }), onSuccess: () => { void Promise.all([client.invalidateQueries({ queryKey: ['records', config.entity] }),client.invalidateQueries({queryKey:['onboarding']})]); closeEditor() }, onError: (e) => setError(e.message) })
  const submit = (rawData: Record<string, string | number>) => {
    const data: RecordValue = { ...rawData, ...(editingId?{id:editingId}:{}) }
    for (const field of config.fields) {
      if (field.type === 'number' && data[field.key]) data[field.key] = Number(data[field.key]) as never
      if (field.type === 'datetime-local' && data[field.key]) data[field.key] = new Date(String(data[field.key])).getTime() as never
    }
    save.mutate(data)
  }
  return <section><div className="page-intro"><div><span className="eyebrow">Local content data</span><h2>{config.title}</h2><p>{config.description}</p></div><button className={open?'secondary':'primary'} onClick={() => open?closeEditor():(setOpen(true),setEditingId(null))}>{open ? 'Cancel editing' : `Add ${config.title.toLowerCase().replace(/s$/, '')}`}</button></div>
    {open && <form className="editor" onSubmit={handleSubmit(submit)}><div className="editor-heading"><span className="eyebrow">{editingId?'Editing saved record':'New record'}</span>{editingId&&<span className="editing-badge">Changes keep the same record</span>}</div><div className="form-grid">{config.fields.map((field) => <label key={field.key}><span>{field.label}</span><input type={field.type ?? 'text'} placeholder={field.placeholder} {...register(field.key, { required: ['name','title','description','startsAt','endsAt'].includes(field.key), valueAsNumber: field.type === 'number' })}/></label>)}</div>{error && <p className="error" role="alert">{error}</p>}<div className="form-actions"><button className="primary" disabled={save.isPending}>{save.isPending ? 'Saving…' : editingId?'Save changes':'Create record'}</button><button type="button" className="secondary" onClick={closeEditor}>Cancel</button></div></form>}
    <div className="record-list">{records.isLoading ? <p>Loading local records…</p> : records.data?.length ? records.data.map((record) => <article className={editingId===String(record.id)?'record-editing':''} key={String(record.id ?? record.key)}><div><strong>{String(record.name ?? record.title ?? record.key ?? 'Record')}</strong><p>{String(record.description ?? record.brief ?? record.objective ?? record.email ?? 'Saved locally')}</p></div><div className="record-controls"><span className="record-meta">{String(record.status ?? 'Active')}</span><button className="secondary compact" onClick={()=>editRecord(record)}>Edit</button></div></article>) : <div className="empty"><h3>No records yet</h3><p>Add the first one to make verified details available across the app.</p></div>}</div>
  </section>
}

type AdAccount={id:string;provider:'meta'|'google_ads'|'tiktok_ads'|'x_ads';displayName:string;accountId:string;capability:'read_only'|'draft_only';hasSecret:boolean;liveEnabled:false}
type AdDraft={id:string;adAccountId:string;contentItemId:string;name:string;objective:string;budgetCents:number;audience:string[];placements:string[];status:'draft'|'approved';liveEnabled:false}
const adProviderLabels={meta:'Meta Ads',google_ads:'Google & YouTube Ads',tiktok_ads:'TikTok Ads',x_ads:'X Ads'}
function AdsWorkspace(){const client=useQueryClient(),[message,setMessage]=useState(''),[account,setAccount]=useState({provider:'meta' as AdAccount['provider'],displayName:'',accountId:'',capability:'read_only' as AdAccount['capability'],credential:''}),[draft,setDraft]=useState({adAccountId:'',contentItemId:'',name:'',objective:'',budget:'',audience:'Local customers',placements:'Automatic'}),accounts=useQuery({queryKey:['ad-accounts'],queryFn:()=>invoke('ads:listAccounts',{}) as Promise<AdAccount[]>}),drafts=useQuery({queryKey:['ad-drafts'],queryFn:()=>invoke('ads:listDrafts',{}) as Promise<AdDraft[]>}),content=useQuery({queryKey:['content-studio'],queryFn:()=>invoke('content:listStudio',{}) as Promise<StudioItem[]>}),refresh=()=>Promise.all([client.invalidateQueries({queryKey:['ad-accounts']}),client.invalidateQueries({queryKey:['ad-drafts']})]),saveAccount=async(e:React.FormEvent)=>{e.preventDefault();try{await invoke('ads:saveAccount',account);setMessage('Advertising account saved separately from organic publishing.');setAccount({...account,displayName:'',accountId:'',credential:''});await refresh()}catch(err){setMessage(err instanceof Error?err.message:'Ad account setup failed.')}},saveDraft=async(e:React.FormEvent)=>{e.preventDefault();try{await invoke('ads:saveDraft',{adAccountId:draft.adAccountId,contentItemId:draft.contentItemId,name:draft.name,objective:draft.objective,budgetCents:Math.round(Number(draft.budget)*100),audience:draft.audience.split(',').map(x=>x.trim()).filter(Boolean),placements:draft.placements.split(',').map(x=>x.trim()).filter(Boolean)});setMessage('Campaign draft saved locally. Nothing was launched.');await refresh()}catch(err){setMessage(err instanceof Error?err.message:'Campaign draft failed.')}},approve=async(id:string)=>{try{await invoke('ads:approveDraft',{id,confirmBudget:true,confirmNoLaunch:true});setMessage('Budget and creative approved. Live launch remains disabled.');await refresh()}catch(err){setMessage(err instanceof Error?err.message:'Approval failed.')}};return <section><div className="page-intro"><div><span className="eyebrow">Paid media control room</span><h2>Ads workspace</h2><p>Connect advertising accounts, prepare campaign drafts, and approve budgets without granting live launch authority.</p></div><span className="mock-badge">Live delivery locked</span></div>{message&&<div className="settings-message" role="status"><ShieldCheck size={18}/>{message}</div>}<div className="ads-readiness"><article><strong>1 · Account access</strong><span>Separate encrypted credentials</span></article><article><strong>2 · Campaign draft</strong><span>Audience, budget, placement, creative</span></article><article><strong>3 · Human approval</strong><span>Second approval required</span></article><article className="locked"><strong>4 · Launch</strong><span>Provider adapters disabled</span></article></div><div className="ads-columns"><form className="panel ads-form" onSubmit={saveAccount}><span className="eyebrow">Advertising connections</span><h3>Add ad account</h3><label><span>Provider</span><select value={account.provider} onChange={e=>setAccount({...account,provider:e.target.value as AdAccount['provider']})}>{Object.entries(adProviderLabels).map(([id,label])=><option value={id} key={id}>{label}</option>)}</select></label><label><span>Account name</span><input required value={account.displayName} onChange={e=>setAccount({...account,displayName:e.target.value})}/></label><label><span>Ad account ID</span><input required value={account.accountId} onChange={e=>setAccount({...account,accountId:e.target.value})}/></label><label><span>Initial capability</span><select value={account.capability} onChange={e=>setAccount({...account,capability:e.target.value as AdAccount['capability']})}><option value="read_only">Read-only reporting</option><option value="draft_only">Campaign drafts only</option></select></label><label><span>API credential <small>optional</small></span><input type="password" value={account.credential} onChange={e=>setAccount({...account,credential:e.target.value})}/></label><button className="primary">Save ad account</button></form><form className="panel ads-form" onSubmit={saveDraft}><span className="eyebrow">Local campaign builder</span><h3>Create campaign draft</h3><label><span>Ad account</span><select required value={draft.adAccountId} onChange={e=>setDraft({...draft,adAccountId:e.target.value})}><option value="">Choose account</option>{accounts.data?.map(a=><option value={a.id} key={a.id}>{a.displayName}</option>)}</select></label><label><span>Approved content</span><select required value={draft.contentItemId} onChange={e=>setDraft({...draft,contentItemId:e.target.value})}><option value="">Choose creative</option>{content.data?.filter(i=>['approved','scheduled','published'].includes(i.status)).map(i=><option value={i.id} key={i.id}>{i.title}</option>)}</select></label><label><span>Campaign name</span><input required value={draft.name} onChange={e=>setDraft({...draft,name:e.target.value})}/></label><label><span>Objective</span><input required value={draft.objective} onChange={e=>setDraft({...draft,objective:e.target.value})} placeholder="Online orders"/></label><label><span>Proposed budget</span><input required type="number" min="1" step="0.01" value={draft.budget} onChange={e=>setDraft({...draft,budget:e.target.value})}/></label><label><span>Audience</span><input required value={draft.audience} onChange={e=>setDraft({...draft,audience:e.target.value})}/></label><label><span>Placements</span><input required value={draft.placements} onChange={e=>setDraft({...draft,placements:e.target.value})}/></label><button className="primary" disabled={!accounts.data?.length}>Save locked draft</button></form></div><div className="ad-draft-list">{drafts.data?.map(item=><article key={item.id}><div><span className={`content-status status-${item.status}`}>{item.status}</span><h3>{item.name}</h3><p>{item.objective} · ${(item.budgetCents/100).toFixed(2)} proposed budget</p></div>{item.status==='draft'?<button className="primary" onClick={()=>approve(item.id)}>Approve budget and creative</button>:<span className="approved-label"><CheckCircle2 size={16}/> Approved · launch locked</span>}</article>)}</div></section>}

void Calendar
void ScheduleButton

type ScheduledItem={id:string;scheduled_for:number;status:string;title:string;platform:string;account_name:string}
function LiveCalendar(){const client=useQueryClient(),[selected,setSelected]=useState(''),[when,setWhen]=useState(''),items=useQuery({queryKey:['schedule'],queryFn:()=>invoke('schedule:list',{}) as Promise<ScheduledItem[]>}),content=useQuery({queryKey:['content-studio'],queryFn:()=>invoke('content:listStudio',{}) as Promise<StudioItem[]>}),approved=content.data?.filter(i=>i.status==='approved')??[],schedule=async()=>{await invoke('schedule:create',{contentItemId:selected,scheduledFor:new Date(when).getTime()});setSelected('');setWhen('');await Promise.all([client.invalidateQueries({queryKey:['schedule']}),client.invalidateQueries({queryKey:['content-studio']})])},run=async(id:string)=>{await invoke('publishing:attempt',{scheduledPostId:id});await client.invalidateQueries({queryKey:['schedule']})};return <section><div className="page-intro"><div><span className="eyebrow">Supervised delivery</span><h2>Content calendar</h2><p>Your oven queue for scheduled and published posts.</p></div><span className="mock-badge">Manual mock publishing</span></div><div className="schedule-bar"><select value={selected} onChange={e=>setSelected(e.target.value)}><option value="">Choose approved content</option>{approved.map(i=><option value={i.id} key={i.id}>{i.title}</option>)}</select><input type="datetime-local" value={when} onChange={e=>setWhen(e.target.value)}/><button className="primary" disabled={!selected||!when} onClick={schedule}>Add to oven queue</button></div><div className="oven-queue">{items.data?.length?items.data.map(item=><article className="oven-ticket" key={item.id}><time>{new Date(item.scheduled_for).toLocaleString()}</time><div><strong>{item.title}</strong><span>{platformLabels[item.platform]??item.platform} · {item.account_name}</span></div><span className="content-status">{item.status}</span>{item.status!=='published'&&<button className="primary compact" onClick={()=>run(item.id)}>{item.status==='failed'?'Retry mock publish':'Run mock publish'}</button>}</article>):<div className="empty"><h3>Nothing in the oven yet</h3><p>Choose approved content above to schedule it.</p></div>}</div></section>}

function Calendar() { const days = Array.from({length: 35},(_,i)=>i-2); return <section><div className="page-intro"><div><span className="eyebrow">Planning view</span><h2>Content calendar</h2><p>Approved content will appear here before it is scheduled.</p></div><span className="mock-badge">Publishing is mocked</span></div><div className="calendar"><div className="calendar-head"><h3>August 2026</h3></div><div className="weekdays">{['Sun','Mon','Tue','Wed','Thu','Fri','Sat'].map(d=><span key={d}>{d}</span>)}</div><div className="calendar-grid">{days.map((day,i)=><div className={day < 1 ? 'outside' : ''} key={i}>{day > 0 ? day : ''}{day === 7 && <span className="calendar-item">Friday feature · Review</span>}{day === 14 && <span className="calendar-item approved">Pepperoni post · Approved</span>}</div>)}</div></div></section> }

function Media() { const [message,setMessage]=useState(''); const add=async()=>{try{const files=await invoke('media:import',{}) as RecordValue[];setMessage(files.length ? `${files.length} file${files.length===1?'':'s'} imported.`:'No files selected.')}catch(e){setMessage(e instanceof Error?e.message:'Import failed.')}}; return <section><div className="page-intro"><div><span className="eyebrow">Application-controlled storage</span><h2>Media library</h2><p>Import approved brand photos and videos into the local workspace.</p></div><button className="primary" onClick={add}><ImagePlus size={17}/> Import media</button></div><div className="empty media-empty"><ImagePlus size={34}/><h3>Your media library is ready</h3><p>Imported files are copied into protected app storage. Originals stay untouched.</p>{message && <p className="notice">{message}</p>}</div></section> }

type StudioItem = { id:string; title:string; brief:string; status:string; updated_at:number; variants:{id:string;platform:string;copy:string;metadata_json:string}[]; generationJobs:{id:string;provider:string;model:string;prompt:string;status:string}[] }
const draftPlatforms = ['google_business_profile','facebook','instagram','tiktok','threads','youtube_shorts','x']
function agentSources(item:StudioItem):{type:string;label:string}[]{try{return (JSON.parse(item.variants[0]?.metadata_json??'{}') as {sources?:{type:string;label:string}[]}).sources??[]}catch{return[]}}

function ScheduleButton({item,onDone}:{item:StudioItem;onDone:(message:string)=>void}){const client=useQueryClient(),[value,setValue]=useState('');const save=async()=>{try{await invoke('schedule:create',{contentItemId:item.id,scheduledFor:new Date(value).getTime()});onDone('Content added to the oven queue.');await Promise.all([client.invalidateQueries({queryKey:['content-studio']}),client.invalidateQueries({queryKey:['schedule']})])}catch(e){onDone(e instanceof Error?e.message:'Scheduling failed.')}};return <div className="schedule-control"><input aria-label="Schedule date and time" type="datetime-local" value={value} onChange={e=>setValue(e.target.value)}/><button className="primary" disabled={!value} onClick={save}><CalendarDays size={16}/> Schedule</button></div>}

function ContentStudio({onNavigate}:{onNavigate:(page:Page)=>void}) {
  const client=useQueryClient(), [open,setOpen]=useState(false), [message,setMessage]=useState(''), [platforms,setPlatforms]=useState<string[]>(['google_business_profile','facebook','instagram']), [agentObjective,setAgentObjective]=useState(''), [agentWorking,setAgentWorking]=useState(false)
  const {register,handleSubmit,reset}=useForm<{title:string;brief:string;menuItemId:string;promotionId:string}>()
  const items=useQuery({queryKey:['content-studio'],queryFn:()=>invoke('content:listStudio',{}) as Promise<StudioItem[]>})
  const menu=useQuery({queryKey:['records','menuItems'],queryFn:()=>invoke('data:list',{entity:'menuItems'}) as Promise<RecordValue[]>})
  const promotions=useQuery({queryKey:['records','promotions'],queryFn:()=>invoke('data:list',{entity:'promotions'}) as Promise<RecordValue[]>})
  const create=async(data:{title:string;brief:string;menuItemId:string;promotionId:string})=>{try{await invoke('content:createDraft',{title:data.title,brief:data.brief,menuItemId:data.menuItemId||undefined,promotionId:data.promotionId||undefined,platforms});reset();setOpen(false);setMessage('Platform drafts created from your saved business facts.');await client.invalidateQueries({queryKey:['content-studio']})}catch(e){setMessage(e instanceof Error?e.message:'Draft creation failed.')}}
  const transition=async(item:StudioItem,to:string)=>{try{await invoke('content:transition',{contentItemId:item.id,to});setMessage(to==='approved'?'Content approved by you. It is ready to schedule.':`Moved to ${to.replaceAll('_',' ')}.`);await client.invalidateQueries({queryKey:['content-studio']})}catch(e){setMessage(e instanceof Error?e.message:'Status change failed.')}}
  const generate=async(item:StudioItem)=>{try{setMessage('Generating mock media outside the renderer…');await invoke('media:generateForContent',{contentItemId:item.id,prompt:item.brief});setMessage('Mock media generated and held for your review. Nothing was published.');await client.invalidateQueries({queryKey:['content-studio']})}catch(e){setMessage(e instanceof Error?e.message:'Media generation failed.')}}
  const produce=async()=>{if(agentObjective.trim().length<10||!platforms.length)return;setAgentWorking(true);try{const result=await invoke('agent:producePackage',{objective:agentObjective,platforms}) as {variantCount:number;sources:unknown[]};setAgentObjective('');setMessage(`Content Producer created ${result.variantCount} grounded drafts using ${result.sources.length} saved fact sources. Review is required.`);await client.invalidateQueries({queryKey:['content-studio']})}catch(e){setMessage(e instanceof Error?e.message:'The Content Producer could not create this package.')}finally{setAgentWorking(false)}}
  const toggle=(platform:string)=>setPlatforms((value)=>value.includes(platform)?value.filter((item)=>item!==platform):[...value,platform])
  return <section><div className="page-intro"><div><span className="eyebrow">Grounded content creation</span><h2>Content studio</h2><p>Create a separate draft for each platform using only the menu and promotion facts saved in this app.</p></div><div className="button-row intro-actions"><button className="secondary" onClick={()=>onNavigate('assistant')}><Bot size={16}/> Ask AI</button><button className="primary" onClick={()=>setOpen(!open)}>{open?'Close draft form':'Create content'}</button></div></div>
    {message&&<div className="settings-message" role="status"><ShieldCheck size={18}/>{message}</div>}
    <section className="producer-panel"><div className="producer-heading"><div className="producer-mark"><Sparkles size={22}/></div><div><span className="eyebrow">Supervised AI automation</span><h3>Content Producer</h3><p>Describe the business outcome. The producer uses saved facts, prepares every platform version, and stops at draft.</p></div><span className="mock-badge">Mock agent · Review required</span></div><div className="producer-input"><textarea value={agentObjective} onChange={event=>setAgentObjective(event.target.value)} placeholder="Example: Build a Friday dinner content package featuring our current menu and active promotion."/><button className="primary" disabled={agentWorking||agentObjective.trim().length<10||!platforms.length} onClick={produce}>{agentWorking?'Producing…':`Produce ${platforms.length} platform drafts`}<Sparkles size={16}/></button></div><div className="producer-platforms">{draftPlatforms.map(platform=><button key={platform} className={platforms.includes(platform)?'selected':''} onClick={()=>toggle(platform)}>{platformLabels[platform]}</button>)}<span>Uses the latest active menu item and promotion, with source labels on the package.</span></div></section>
    {open&&<form className="content-composer" onSubmit={handleSubmit(create)}><div className="composer-main"><label><span>Working title</span><input {...register('title',{required:true})} placeholder="Friday night pizza reminder"/></label><label><span>What should this post communicate?</span><textarea {...register('brief',{required:true,minLength:10})} placeholder="Invite customers to order ahead for Friday dinner."/></label><div className="source-grid"><label><span>Verified menu item <small>optional</small></span><select {...register('menuItemId')}><option value="">No menu item</option>{menu.data?.map(item=><option key={String(item.id)} value={String(item.id)}>{String(item.name)}</option>)}</select></label><label><span>Active promotion <small>optional</small></span><select {...register('promotionId')}><option value="">No promotion</option>{promotions.data?.map(item=><option key={String(item.id)} value={String(item.id)}>{String(item.name)}</option>)}</select></label></div></div><div className="platform-picker"><span className="eyebrow">Create variants for</span>{draftPlatforms.map(platform=><label key={platform}><input type="checkbox" checked={platforms.includes(platform)} onChange={()=>toggle(platform)}/><span>{platformLabels[platform]}</span></label>)}<button className="primary" disabled={!platforms.length}>Create {platforms.length} draft{platforms.length===1?'':'s'}</button><small>Drafts remain local until you approve and schedule them.</small></div></form>}
    <div className="studio-list">{items.isLoading?<p>Loading content…</p>:items.data?.length?items.data.map(item=><article className="studio-item" key={item.id}><header><div><span className={`content-status status-${item.status}`}>{item.status.replaceAll('_',' ')}</span><h3>{item.title}</h3><p>{item.brief}</p>{agentSources(item).length>0&&<div className="fact-sources"><span>Based on</span>{agentSources(item).map(source=><strong key={`${source.type}-${source.label}`}>{source.label}</strong>)}</div>}{item.generationJobs?.[0]&&<span className="generation-note"><Sparkles size={13}/> {item.generationJobs[0].status==='completed'?'Mock image ready for review':`Media job: ${item.generationJobs[0].status}`}</span>}</div><div className="review-actions">{item.status==='draft'&&<><button className="secondary" onClick={()=>transition(item,'ready_for_review')}>Copy only · Review</button><button className="primary" onClick={()=>generate(item)}><Sparkles size={16}/> Generate mock media</button></>}{item.status==='ready_for_review'&&<><button className="secondary" onClick={()=>transition(item,'draft')}>Return to draft</button><button className="primary" onClick={()=>transition(item,'approved')}><CheckCircle2 size={16}/> Approve content</button></>}{item.status==='approved'&&<span className="approved-label"><CheckCircle2 size={16}/> Approved by you</span>}</div></header><div className="variant-grid">{item.variants.map(variant=><section key={variant.id}><span>{platformLabels[variant.platform]??variant.platform}</span><p>{variant.copy}</p></section>)}</div></article>):<div className="empty"><h3>No content drafts yet</h3><p>Create the first idea and choose the platforms that need their own version.</p></div>}</div>
  </section>
}

type ChatMessage={id:string;role:'user'|'assistant';content:string;provider:string;model:string;created_at:number}
function AiAssistant({onNavigate}:{onNavigate:(page:Page)=>void}){
  const client=useQueryClient(),[draft,setDraft]=useState(''),[error,setError]=useState('')
  const messages=useQuery({queryKey:['ai-chat'],queryFn:()=>invoke('ai:listChat',{}) as Promise<ChatMessage[]>})
  const config=useQuery({queryKey:['ai-config'],queryFn:()=>invoke('ai:getConfig',{}) as Promise<{provider:string;model:string;liveEnabled:boolean}>})
  const send=useMutation({mutationFn:(content:string)=>invoke('ai:sendChat',{content}),onSuccess:()=>{setDraft('');setError('');void client.invalidateQueries({queryKey:['ai-chat']})},onError:(failure)=>setError(failure.message)})
  const submit=(event:React.FormEvent)=>{event.preventDefault();if(draft.trim().length>=2)send.mutate(draft.trim())}
  const clear=async()=>{await invoke('ai:clearChat',{});await client.invalidateQueries({queryKey:['ai-chat']})}
  const suggestions=['Plan five posts for next week','Turn my active promotion into a campaign','Suggest a short video concept','What facts are missing from my profile?']
  return <section className="assistant-page"><div className="page-intro"><div><span className="eyebrow">Supervised workspace assistant</span><h2>AI Assistant</h2><p>Plan and develop content with your saved business facts. The assistant cannot approve, schedule, or publish.</p></div><div className="assistant-provider"><span className={config.data?.liveEnabled?'status-dot':'status-dot offline'}/><strong>{config.data?.provider.replaceAll('_',' ')??'Local mock'}</strong><small>{config.data?.model??'local-deterministic-v1'}</small></div></div>
    <div className="assistant-layout"><div className="chat-shell"><div className="chat-toolbar"><span><Bot size={16}/> Content planning conversation</span><button className="text-button" onClick={clear}><Trash2 size={14}/> Clear</button></div><div className="chat-history">{messages.isLoading?<p>Loading conversation…</p>:messages.data?.length?messages.data.map(message=><article className={`chat-message ${message.role}`} key={message.id}><div className="message-avatar">{message.role==='assistant'?<Bot size={16}/>:<span>You</span>}</div><div><span>{message.role==='assistant'?'Pizza Promo AI':'You'}</span><p>{message.content}</p>{message.role==='assistant'&&<small>{message.provider} · {message.model}</small>}</div></article>):<div className="chat-welcome"><div className="producer-mark"><Bot size={22}/></div><h3>What are you working on?</h3><p>Ask for a campaign direction, platform approach, production checklist, or ways to use the facts already saved in Pizza Promo Pro.</p><div>{suggestions.map(suggestion=><button key={suggestion} onClick={()=>setDraft(suggestion)}>{suggestion}</button>)}</div></div>}</div><form className="chat-composer" onSubmit={submit}><textarea value={draft} onChange={event=>setDraft(event.target.value)} placeholder="Ask about content, promotions, campaigns, or production…"/><button className="primary" disabled={send.isPending||draft.trim().length<2}>{send.isPending?'Thinking…':<><Send size={16}/> Send</>}</button></form>{error&&<p className="chat-error">{error}</p>}</div>
      <aside className="assistant-context"><span className="eyebrow">Useful next moves</span><h3>From conversation to work</h3><button onClick={()=>onNavigate('contentItems')}><Sparkles size={17}/><span><strong>Open Content Studio</strong><small>Turn the direction into reviewable drafts</small></span><ChevronRight size={15}/></button><button onClick={()=>onNavigate('menuItems')}><MenuIcon size={17}/><span><strong>Review menu facts</strong><small>Improve grounding and pricing accuracy</small></span><ChevronRight size={15}/></button><button onClick={()=>onNavigate('settings')}><Settings size={17}/><span><strong>Choose AI provider</strong><small>Connect a customer-owned model API</small></span><ChevronRight size={15}/></button><div className="assistant-boundary"><ShieldCheck size={19}/><strong>Human control stays on</strong><p>Chat responses are advice. They never change content status or trigger external services.</p></div></aside></div>
  </section>
}

type AiConfig={provider:'local_mock'|'openai'|'openai_compatible'|'ollama';model:string;endpoint:string;hasApiKey:boolean;liveEnabled:boolean;updatedAt:number}
function AiProviderSettings({onMessage}:{onMessage:(message:string)=>void}){
  const client=useQueryClient(),config=useQuery({queryKey:['ai-config'],queryFn:()=>invoke('ai:getConfig',{}) as Promise<AiConfig>}),[form,setForm]=useState({provider:'local_mock' as AiConfig['provider'],model:'local-deterministic-v1',endpoint:'',apiKey:''}),[working,setWorking]=useState(false)
  const installedModels=useQuery({queryKey:['ai-models',config.data?.provider],queryFn:()=>invoke('ai:listModels',{}) as Promise<string[]>,enabled:config.data?.provider==='ollama',retry:false})
  useEffect(()=>{if(config.data)setForm(value=>({...value,provider:config.data!.provider,model:config.data!.model,endpoint:config.data!.endpoint}))},[config.data])
  const save=async(event:React.FormEvent)=>{event.preventDefault();setWorking(true);try{await invoke('ai:saveConfig',form);onMessage('AI provider setup saved securely.');setForm(value=>({...value,apiKey:''}));await client.invalidateQueries({queryKey:['ai-config']})}catch(error){onMessage(error instanceof Error?error.message:'AI provider setup failed.')}finally{setWorking(false)}}
  const test=async()=>{setWorking(true);try{const result=await invoke('ai:testConnection',{}) as {message:string};onMessage(result.message)}catch(error){onMessage(error instanceof Error?error.message:'Connection test failed.')}finally{setWorking(false)}}
  const statusLabel=config.data?.provider==='ollama'?'Local Ollama':config.data?.liveEnabled?'Customer API':'Local mock'
  return <section className="connection-section ai-provider-section"><div className="section-heading"><div><span className="eyebrow">Content intelligence</span><h3>AI Content Provider</h3><p className="section-copy">Use the built-in local mock, run a model locally with Ollama, or connect a customer-owned API.</p></div><span className={config.data?.liveEnabled?'setup-state configured':'setup-state'}>{statusLabel}</span></div><form className="ai-provider-form" onSubmit={save}><label><span>Provider</span><select value={form.provider} onChange={event=>{const provider=event.target.value as AiConfig['provider'];setForm({...form,provider,endpoint:provider==='openai'?'https://api.openai.com/v1':provider==='ollama'?'http://localhost:11434':provider==='local_mock'?'':form.endpoint,model:provider==='local_mock'?'local-deterministic-v1':provider==='ollama'?'gemma3':form.model})}}><option value="local_mock">Local Mock — no model required</option><option value="ollama">Ollama — local AI</option><option value="openai">OpenAI</option><option value="openai_compatible">OpenAI-compatible API</option></select></label><label><span>Model</span><input required list="installed-ai-models" value={form.model} disabled={form.provider==='local_mock'} onChange={event=>setForm({...form,model:event.target.value})} placeholder={form.provider==='ollama'?'Example: gemma3':'Model name from your provider'}/><datalist id="installed-ai-models">{installedModels.data?.map(model=><option value={model} key={model}/>)}</datalist>{form.provider==='ollama'&&<small>{installedModels.data?.length?`${installedModels.data.length} installed model${installedModels.data.length===1?'':'s'} found.`:'Save the Ollama setup to discover installed models.'}</small>}</label>{form.provider!=='local_mock'&&<label><span>{form.provider==='ollama'?'Ollama server':'API endpoint'}</span><input required type="url" value={form.endpoint} disabled={form.provider==='openai'} onChange={event=>setForm({...form,endpoint:event.target.value})}/></label>}{!['local_mock','ollama'].includes(form.provider)&&<label><span>API key</span><input type="password" autoComplete="off" value={form.apiKey} onChange={event=>setForm({...form,apiKey:event.target.value})} placeholder={config.data?.hasApiKey?'Leave blank to keep saved key':'Paste provider API key'}/></label>}<div className="ai-provider-actions"><button className="primary" disabled={working}>Save provider</button><button type="button" className="secondary" disabled={working} onClick={test}>Test connection</button><span><ShieldCheck size={14}/>{form.provider==='ollama'?'Local requests stay on this computer':'Key encrypted on this computer'}</span></div></form></section>
}

type PerformanceRow={sourceType:'organic_post'|'ad_campaign';sourceId:string;platform:string;label:string;impressions:number;reach:number;engagements:number;clicks:number;spendCents:number|null;conversions:number|null;revenueCents:number|null;engagementRate:number;clickThroughRate:number;capturedAt:number;dataSource:'local_sample'|'manual'|'live'}
type PerformanceOverview={summary:{impressions:number;reach:number;engagements:number;clicks:number;spendCents:number;conversions:number;revenueCents:number;engagementRate:number;clickThroughRate:number;returnOnAdSpend:number|null};rows:PerformanceRow[];freshness:{generatedAt:number;latestCapturedAt:number|null;dataSources:string[];hasData:boolean;message:string}}
const whole=new Intl.NumberFormat('en-US'),money=(cents:number)=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format(cents/100),rate=(value:number)=>`${(value*100).toFixed(1)}%`
function PerformanceWorkspace(){const client=useQueryClient(),[message,setMessage]=useState(''),overview=useQuery({queryKey:['analytics-overview'],queryFn:()=>invoke('analytics:getOverview',{}) as Promise<PerformanceOverview>}),sample=async()=>{try{const result=await invoke('analytics:generateSample',{}) as PerformanceOverview;setMessage(result.freshness.message);await client.invalidateQueries({queryKey:['analytics-overview']})}catch(e){setMessage(e instanceof Error?e.message:'Sample reporting could not be generated.')}},data=overview.data;return <section><div className="page-intro"><div><span className="eyebrow">Outcome reporting</span><h2>Performance</h2><p>Compare organic and paid content with its source and freshness always visible.</p></div><button className="primary" onClick={sample}>Generate local sample</button></div>{message&&<div className="settings-message" role="status"><ShieldCheck size={18}/>{message}</div>}<div className="performance-source"><span className="mock-badge">{data?.freshness.dataSources.join(' + ').replaceAll('_',' ')||'No data source'}</span><p>{data?.freshness.latestCapturedAt?`Latest snapshot ${new Date(data.freshness.latestCapturedAt).toLocaleString()}`:'No snapshots collected yet.'}</p></div><div className="outcome-strip"><article><span>Reach</span><strong>{whole.format(data?.summary.reach??0)}</strong></article><article><span>Engagement rate</span><strong>{rate(data?.summary.engagementRate??0)}</strong></article><article><span>Clicks</span><strong>{whole.format(data?.summary.clicks??0)}</strong></article><article><span>Ad spend</span><strong>{money(data?.summary.spendCents??0)}</strong></article><article><span>Conversions</span><strong>{whole.format(data?.summary.conversions??0)}</strong></article><article><span>Return on ad spend</span><strong>{data?.summary.returnOnAdSpend===null?'—':`${data?.summary.returnOnAdSpend.toFixed(2)}×`}</strong></article></div><div className="performance-table"><header><span>Content</span><span>Reach</span><span>Engaged</span><span>Clicks</span><span>Spend</span><span>Return</span></header>{data?.rows.length?data.rows.map(row=><article key={`${row.sourceType}-${row.sourceId}`}><div><span className={`source-pill ${row.sourceType}`}>{row.sourceType==='ad_campaign'?'Paid':'Organic'}</span><strong>{row.label}</strong><small>{row.platform.replaceAll('_',' ')} · {row.dataSource.replaceAll('_',' ')}</small></div><span>{whole.format(row.reach)}</span><span>{rate(row.engagementRate)}</span><span>{whole.format(row.clicks)}</span><span>{row.spendCents===null?'—':money(row.spendCents)}</span><span>{row.spendCents&&row.revenueCents!==null?`${(row.revenueCents/row.spendCents).toFixed(2)}×`:'—'}</span></article>):<div className="empty"><h3>No attributable performance yet</h3><p>{data?.freshness.message??'Publish content or approve a paid campaign draft, then generate a local sample.'}</p></div>}</div><p className="reporting-boundary"><ShieldCheck size={15}/> Local sample data is deterministic and clearly labeled. Live provider reporting remains disabled.</p></section>}

type OnboardingStep={id:string;label:string;status:'complete'|'next'|'optional';description:string;target:'businesses'|'locations'|'brandProfiles'|'menuItems'|'settings'|'ads'}
type OnboardingStatus={shouldShow:boolean;dismissed:boolean;completionPercent:number;essentialComplete:boolean;steps:OnboardingStep[]}
function SetupWorkspace({onNavigate}:{onNavigate:(page:Page)=>void}){const client=useQueryClient(),status=useQuery({queryKey:['onboarding'],queryFn:()=>invoke('onboarding:getStatus',{}) as Promise<OnboardingStatus>}),dismiss=async()=>{await invoke('onboarding:setDismissed',{dismissed:true});await client.invalidateQueries({queryKey:['onboarding']});onNavigate('overview')},data=status.data,essentials=data?.steps.slice(0,4)??[],recommended=data?.steps.slice(4)??[];return <section><div className="setup-hero"><div className="readiness-dial" style={{'--progress':`${data?.completionPercent??0}%`} as React.CSSProperties}><strong>{data?.completionPercent??0}%</strong><span>ready</span></div><div><span className="eyebrow">Workspace mise en place</span><h2>Prepare the facts. Then create with confidence.</h2><p>Pizza Promo Pro uses these details to keep AI content accurate, platform-ready, and under your control.</p></div>{data&&!data.essentialComplete&&<button className="text-button" onClick={dismiss}>Finish later</button>}</div><div className="setup-section"><div className="section-heading"><div><span className="eyebrow">Required foundation</span><h3>Essential ingredients</h3></div><span className="count-badge">{essentials.filter(s=>s.status==='complete').length} of 4 ready</span></div><div className="setup-steps">{essentials.map((step,index)=><article className={`setup-step ${step.status}`} key={step.id}><span className="step-number">{step.status==='complete'?<CheckCircle2 size={18}/>:String(index+1).padStart(2,'0')}</span><div><strong>{step.label}</strong><p>{step.description}</p></div><button className={step.status==='next'?'primary compact':'secondary compact'} onClick={()=>onNavigate(step.target as Page)}>{step.status==='complete'?'Review':'Set up'}<ChevronRight size={14}/></button></article>)}</div></div><div className="setup-section recommended"><div className="section-heading"><div><span className="eyebrow">Expand the workspace</span><h3>Recommended connections</h3></div><span className="mock-badge">Optional</span></div><div className="setup-steps">{recommended.map(step=><article className={`setup-step ${step.status}`} key={step.id}><span className="step-number">{step.status==='complete'?<CheckCircle2 size={18}/>:<Link2 size={18}/>}</span><div><strong>{step.label}</strong><p>{step.description}</p></div><button className="secondary compact" onClick={()=>onNavigate(step.target as Page)}>{step.status==='complete'?'Review':'Connect'}<ChevronRight size={14}/></button></article>)}</div></div>{data?.essentialComplete&&<div className="setup-complete"><CheckCircle2 size={24}/><div><strong>Your content foundation is ready.</strong><p>You can begin creating grounded platform drafts now and add connections whenever you need them.</p></div><button className="primary" onClick={()=>onNavigate('contentItems')}>Open Content Studio</button></div>}</section>}

type Connection = { id: string; kind: 'social' | 'higgsfield_mcp'; provider: string; displayName: string; accountId?: string; endpoint?: string; status: 'configured' | 'needs_setup'; liveEnabled: boolean; hasSecret: boolean; updatedAt: number }
const platformLabels: Record<string, string> = { google_business_profile: 'Google Business Profile', facebook: 'Facebook', instagram: 'Instagram', tiktok: 'TikTok', threads: 'Threads', youtube_shorts: 'YouTube Shorts', x: 'X' }

type UpdateStatus={state:'idle'|'checking'|'available'|'downloading'|'downloaded'|'up_to_date'|'error'|'unavailable';currentVersion:string;availableVersion:string|null;progressPercent:number|null;message:string}
function ApplicationUpdates({onMessage}:{onMessage:(message:string)=>void}){
  const status=useQuery({queryKey:['update-status'],queryFn:()=>invoke('updates:getStatus',{}) as Promise<UpdateStatus>,refetchInterval:2000}),[working,setWorking]=useState(false),data=status.data
  const act=async(channel:'updates:check'|'updates:download'|'updates:install')=>{setWorking(true);try{const result=await invoke(channel,{}) as UpdateStatus;onMessage(result.message);await status.refetch()}catch(error){onMessage(error instanceof Error?error.message:'The update action could not be completed.')}finally{setWorking(false)}}
  const busy=working||data?.state==='checking'||data?.state==='downloading'
  return <section className="connection-section update-section"><div className="section-heading"><div><span className="eyebrow">Application delivery</span><h3>Pizza Promo Pro updates</h3><p className="section-copy">Installed builds check GitHub Releases automatically. Updates download quietly and install only when you choose to restart.</p></div><span className={`setup-state ${['up_to_date','downloaded'].includes(data?.state??'')?'configured':''}`}>{data?.state.replaceAll('_',' ')??'Loading'}</span></div><div className="update-layout"><div className="update-version"><Download size={24}/><div><strong>Version {data?.currentVersion??'…'}</strong><p>{data?.message??'Reading update status…'}</p>{data?.availableVersion&&<small>Available version {data.availableVersion}</small>}</div></div>{data?.progressPercent!==null&&data?.progressPercent!==undefined&&<div className="update-progress" aria-label={`Update download ${data.progressPercent}%`}><span style={{width:`${data.progressPercent}%`}}/></div>}<div className="button-row"><button className="secondary" disabled={busy} onClick={()=>act('updates:check')}><RefreshCw size={15}/> Check for updates</button>{data?.state==='available'&&<button className="primary" disabled={busy} onClick={()=>act('updates:download')}><Download size={15}/> Download update</button>}{data?.state==='downloaded'&&<button className="primary" disabled={working} onClick={()=>act('updates:install')}>Restart and update</button>}</div></div></section>
}

function SettingsPage() {
  const client = useQueryClient(), [message,setMessage]=useState(''), [selectedPlatform,setSelectedPlatform]=useState(''), [socialForm,setSocialForm]=useState({displayName:'',accountId:'',accessToken:''}), [higgsfield,setHiggsfield]=useState({endpoint:'',accessToken:''})
  const connections = useQuery({ queryKey:['connections'], queryFn:()=>invoke('connections:list',{}) as Promise<Connection[]> })
  const refresh = () => client.invalidateQueries({queryKey:['connections']})
  const saveSocial = async (event: React.FormEvent) => { event.preventDefault(); try { await invoke('connections:saveSocial',{platform:selectedPlatform, ...socialForm}); setMessage(`${platformLabels[selectedPlatform]} setup saved securely. Live publishing remains disabled.`); setSelectedPlatform(''); setSocialForm({displayName:'',accountId:'',accessToken:''}); await refresh() } catch(e){setMessage(e instanceof Error?e.message:'Connection setup failed.')} }
  const saveHiggsfield = async (event: React.FormEvent) => { event.preventDefault(); try { await invoke('connections:saveHiggsfield',{endpoint:higgsfield.endpoint,...(higgsfield.accessToken.trim()?{accessToken:higgsfield.accessToken}: {})}); setMessage('Higgsfield MCP setup saved securely. The access token remains optional.'); setHiggsfield((value)=>({...value,accessToken:''})); await refresh() } catch(e){setMessage(e instanceof Error?e.message:'Higgsfield setup failed.')} }
  const check = async (connection:Connection) => { try { setMessage(connection.kind==='higgsfield_mcp'?'Contacting the MCP server…':'Checking setup…'); const result=await invoke('connections:check',{id:connection.id,kind:connection.kind}) as {message:string}; setMessage(result.message) } catch(e){setMessage(e instanceof Error?e.message:'Connection check failed.')} }
  const remove = async (connection:Connection) => { await invoke('connections:remove',{id:connection.id,kind:connection.kind}); setMessage(`${connection.displayName} removed.`); await refresh() }
  const backup=async()=>{const r=await invoke('backup:create',{}) as {path:string};setMessage(r.path?'Backup created successfully.':'Backup canceled.')}
  const restore=async()=>{const r=await invoke('backup:restore',{}) as {restored:boolean};setMessage(r.restored?'Backup restored. Restart the app to load it.':'Restore canceled.')}
  const saved = connections.data ?? [], higgsfieldConnection=saved.find((item)=>item.kind==='higgsfield_mcp')
  return <section>
    <div className="page-intro"><div><span className="eyebrow">Connections and workspace</span><h2>Settings</h2><p>Prepare the accounts and tools Pizza Promo Pro will use. Credentials stay encrypted on this computer.</p></div><span className="mock-badge">Live adapters off</span></div>
    {message&&<div className="settings-message" role="status"><ShieldCheck size={18}/>{message}</div>}
    <ApplicationUpdates onMessage={setMessage}/>
    <AiProviderSettings onMessage={setMessage}/>
    <section className="connection-section"><div className="section-heading"><div><span className="eyebrow">Publishing destinations</span><h3>Social media accounts</h3><p className="section-copy">Save account details now. OAuth verification and live publishing will be enabled one platform at a time.</p></div><span className="count-badge">{saved.filter((item)=>item.kind==='social').length} of 7 set up</span></div>
      <div className="connection-grid">{Object.entries(platformLabels).map(([platform,label])=>{const connected=saved.find((item)=>item.provider===platform);return <article className="connection-card" key={platform}><div className={`platform-mark platform-${platform}`}>{label.slice(0,1)}</div><div className="connection-copy"><strong>{label}</strong><span>{connected ? connected.displayName : 'Not set up'}</span></div><span className={connected?'setup-state configured':'setup-state'}>{connected?'Setup saved':'Needs setup'}</span><div className="connection-actions">{connected?<><button className="text-button" onClick={()=>check(connected)}>Check setup</button><button className="icon-button" aria-label={`Remove ${label}`} onClick={()=>remove(connected)}><Unplug size={15}/></button></>:<button className="secondary compact" onClick={()=>setSelectedPlatform(platform)}>Set up</button>}</div></article>})}</div>
      {selectedPlatform&&<form className="connection-form" onSubmit={saveSocial}><div><span className="eyebrow">Account setup</span><h3>{platformLabels[selectedPlatform]}</h3><p>This saves account metadata and an optional encrypted token. It does not publish or open OAuth yet.</p></div><label><span>Account name</span><input required value={socialForm.displayName} onChange={e=>setSocialForm({...socialForm,displayName:e.target.value})} placeholder="Downtown store"/></label><label><span>Account or page ID</span><input required value={socialForm.accountId} onChange={e=>setSocialForm({...socialForm,accountId:e.target.value})} placeholder="Your platform account ID"/></label><label><span>Access token <small>optional</small></span><input type="password" autoComplete="off" value={socialForm.accessToken} onChange={e=>setSocialForm({...socialForm,accessToken:e.target.value})} placeholder="Stored with system encryption"/></label><div className="form-actions"><button type="button" className="secondary" onClick={()=>setSelectedPlatform('')}>Cancel</button><button className="primary">Save setup</button></div></form>}
    </section>
    <section className="connection-section higgsfield-section"><div className="section-heading"><div><span className="eyebrow">Media generation</span><h3>Higgsfield MCP</h3><p className="section-copy">Point the app to your Higgsfield MCP server. Check connection verifies the server and discovers its tools without running any of them.</p></div>{higgsfieldConnection&&<span className="setup-state configured">Setup saved</span>}</div>
      <div className="higgsfield-layout"><div className="provider-identity"><div className="higgsfield-mark"><Sparkles size={24}/></div><div><strong>Higgsfield MCP connection</strong><p>{higgsfieldConnection?.endpoint ?? 'No endpoint configured'}</p><span>{higgsfieldConnection?.hasSecret?'Encrypted token stored':'Public endpoint · no token stored'}</span></div></div><form onSubmit={saveHiggsfield}><label><span>MCP server URL</span><input required type="url" value={higgsfield.endpoint} onChange={e=>setHiggsfield({...higgsfield,endpoint:e.target.value})} placeholder={higgsfieldConnection?.endpoint ?? 'https://your-mcp-server.example.com/mcp'}/></label><label><span>Access token <small>optional</small></span><input type="password" autoComplete="off" value={higgsfield.accessToken} onChange={e=>setHiggsfield({...higgsfield,accessToken:e.target.value})} placeholder={higgsfieldConnection?.hasSecret?'Leave blank to keep saved token':'Only needed when the server requires it'}/></label><div className="button-row"><button className="primary"><Link2 size={16}/> Save MCP setup</button>{higgsfieldConnection&&<><button type="button" className="secondary" onClick={()=>check(higgsfieldConnection)}>Check connection</button><button type="button" className="text-button danger" onClick={()=>remove(higgsfieldConnection)}>Remove</button></>}</div></form></div>
    </section>
    <div className="settings-grid utility-settings"><article className="panel"><Database size={24}/><h3>Local backup</h3><p>Save a portable copy of your content database and media. Encrypted provider credentials are excluded.</p><div className="button-row"><button className="primary" onClick={backup}>Create backup</button><button className="secondary" onClick={restore}>Restore backup</button></div></article><article className="panel quiet"><ShieldCheck size={24}/><h3>Security boundary</h3><p>Tokens never appear after saving and never enter the React renderer again. Live provider calls remain disabled until their adapters are enabled.</p></article></div>
  </section>
}

type CopyWarning={code:string;message:string;severity:'warning'}
const copyLimits:Record<string,number>={google_business_profile:1500,facebook:63206,instagram:2200,tiktok:2200,threads:500,youtube_shorts:100,x:280}
function VariantProof({variant,editable,onSaved}:{variant:StudioItem['variants'][number];editable:boolean;onSaved:()=>void}){const [copy,setCopy]=useState(variant.copy),[editing,setEditing]=useState(false),[warnings,setWarnings]=useState<CopyWarning[]>([]),[message,setMessage]=useState(''),limit=copyLimits[variant.platform]??70000,save=async()=>{try{const result=await invoke('content:updateVariant',{variantId:variant.id,copy}) as {warnings:CopyWarning[]};setWarnings(result.warnings);setEditing(false);setMessage(result.warnings.length?'Saved with items to verify. Content returned to draft review.':'Saved. Content returned to draft review.');onSaved()}catch(e){setMessage(e instanceof Error?e.message:'Copy could not be saved.')}};return <article className={`proof-sheet ${warnings.length?'has-warnings':''}`}><header><span>{platformLabels[variant.platform]??variant.platform}</span><strong className={copy.length>limit?'over-limit':''}>{copy.length} / {limit}</strong></header>{editing?<textarea value={copy} onChange={e=>setCopy(e.target.value)} autoFocus/>:<p>{copy}</p>}<div className="proof-actions">{editable?(editing?<><button className="primary compact" onClick={save}>Save copy</button><button className="text-button" onClick={()=>{setCopy(variant.copy);setEditing(false)}}>Cancel</button></>:<button className="secondary compact" onClick={()=>setEditing(true)}>Edit platform copy</button>):<span className="locked-copy"><ShieldCheck size={14}/> Locked after approval</span>}</div>{warnings.length>0&&<div className="proof-warnings">{warnings.map(w=><div key={w.code}><span>!</span><p>{w.message}</p></div>)}</div>}{message&&<small className="proof-message">{message}</small>}</article>}
function ReviewDesk(){const client=useQueryClient(),items=useQuery({queryKey:['content-studio'],queryFn:()=>invoke('content:listStudio',{}) as Promise<StudioItem[]>}),refresh=()=>{void client.invalidateQueries({queryKey:['content-studio']})};return <section><div className="page-intro"><div><span className="eyebrow">Editorial proofing</span><h2>Review desk</h2><p>Edit each platform version, check its character limit, and resolve factual risks before approval.</p></div><span className="mock-badge">Source-aware checks</span></div><div className="review-legend"><span><i className="verified"/> Source-backed</span><span><i className="warning"/> Needs verification</span><span><i className="locked"/> Approved copy locked</span></div><div className="review-stack">{items.data?.length?items.data.map(item=><section className="review-package" key={item.id}><header><div><span className={`content-status status-${item.status}`}>{item.status.replaceAll('_',' ')}</span><h3>{item.title}</h3></div><small>{item.variants.length} platform version{item.variants.length===1?'':'s'}</small></header><div className="proof-grid">{item.variants.map(variant=><VariantProof key={variant.id} variant={variant} editable={['draft','ready_for_review'].includes(item.status)} onSaved={refresh}/>)}</div></section>):<div className="empty"><h3>No copy to review</h3><p>Create content in Content Studio, then return here to proof every platform version.</p></div>}</div></section>}
